# Let me take a simpler approach - extract fiscal year data directly
# This is what the Treasury Bulletin primarily tracks

import os
import re

fiscal_years = {}

for file_year in range(1990, 2015):
    filepath = f"/app/corpus/treasury_bulletin_{file_year}_12.txt"

    if not os.path.exists(filepath):
        continue

    with open(filepath, 'r') as f:
        content = f.read()

    lines = content.split('\n')

    for line in lines:
        # Match lines with just a year (fiscal year entries)
        if re.match(r'^\| (19[89][0-9]|20[0-1][0-9]) \|', line):
            # Skip lines with "Est", months, etc
            if 'Est' in line or re.search(r'[A-Za-z]', line.split('|')[2] if len(line.split('|')) > 2 else ' '):
                continue

            parts = [p.strip() for p in line.split('|') if p.strip()]

            if len(parts) >= 8:
                try:
                    year = int(parts[0])

                    if year < 1989 or year > 2013:
                        continue

                    if year in fiscal_years:
                        continue

                    # Verify numeric values
                    receipts = parts[1].replace(',', '').replace('r', '')
                    if not receipts.isdigit():
                        continue
                    receipts = int(receipts)

                    # Main budget table has receipts 900K-3500K
                    if 900000 <= receipts <= 3500000:
                        deficit = int(parts[7].replace(',', '').replace('r', ''))
                        fiscal_years[year] = deficit
                except:
                    pass

# Print sorted results
print("=== Fiscal Year Surplus/Deficit (1989-2013) ===")
data = []
for y in range(1989, 2014):
    if y in fiscal_years:
        val = fiscal_years[y]
        print(f"FY{y}: {val}")
        data.append((y, val))
    else:
        print(f"FY{y}: MISSING")

print("\nData:", data)
EOF

